import { OrderEventKind } from "../domain/order";

const KIND_CODE: Record<OrderEventKind, string> = {
  PAID: "paid",
  SHIPPED: "ship",
  DELIVERED: "dlvd",
};

/**
 * 알림 메시지 키 — `<논리 키 해시 16자>.<네임스페이스>.<이벤트>.<업무 식별자>`.
 * mqpub은 한 배치 안에서 키 앞 16바이트가 같으면 첫 메시지만 저장하고 나머지를 조용히 버린다.
 * 공통 접두(네임스페이스·이벤트명)가 길면 식별자 부분이 16바이트 밖으로 밀리므로,
 * 앞 16바이트에 논리 키 전체의 결정적 해시를 둔다. 소비 측 중복 방지도 이 키를 쓴다.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
  const digest = createHash("sha256").update(logical, "utf8").digest("hex").slice(0, 16);
  return `${digest}.${logical}`;
}

